<?php get_header(); ?><main><section class="page-hero"><div class="container"><p class="eyebrow">Seven S Racing</p><h1 class="display"><?php echo is_home() ? 'Race Reports' : esc_html(get_the_title()); ?></h1></div></section><section class="content-section"><div class="container"><div class="post-grid"><?php if(have_posts()):while(have_posts()):the_post(); ?><a class="post-card" href="<?php the_permalink(); ?>"><div class="post-card__media"><?php if(has_post_thumbnail()) the_post_thumbnail('seven-s-card'); ?></div><div class="post-card__body"><span class="eyebrow"><?php echo esc_html(get_the_date()); ?></span><h3><?php the_title(); ?></h3><p><?php echo esc_html(wp_trim_words(get_the_excerpt(),20)); ?></p></div></a><?php endwhile;else:?><p>No race reports have been posted yet.</p><?php endif;?></div></div></section></main><?php get_footer(); ?>

